"""Learning hub: courses (a /learn run that has a path), flashcards with spaced repetition, activity log, practice labs.

Everything that can be exact is exact code, not model output:
* flashcard scheduling is SM-2 (the algorithm behind Anki), computed here;
* math practice problems are generated by templates with seeded randomness and their answers are computed with Python/sympy;
* code-lab exercises are only shown after the model's own solution passes the model's own tests in the sandbox;
* progress, streaks and weak topics are counted from logged events, never estimated by the model.
"""
from __future__ import annotations

import asyncio
import json
import math
import os
import random
import re
import statistics
import sys
import time
import uuid
from datetime import date, datetime, timedelta
from fractions import Fraction
from typing import Any, Optional

from . import db, flashcards

GRADES = {"again": 0, "hard": 3, "good": 4, "easy": 5}
MAX_CARDS_PER_LESSON = 10


# ------------------------------------------------------------------ helpers
def _now() -> float:
    return time.time()


def _end_of_today() -> float:
    n = datetime.now()
    return datetime(n.year, n.month, n.day).timestamp() + 86400


def _day(ts: float) -> str:
    return datetime.fromtimestamp(ts).strftime("%Y-%m-%d")


def _norm(t: str) -> str:
    return re.sub(r"[^a-z0-9]+", " ", (t or "").lower()).strip()


# ------------------------------------------------------------------ courses
def _runs() -> list[dict]:
    with db.conn() as c:
        # a course lives in its chat: when the chat is deleted the course goes with it (it could not be continued anyway)
        rows = c.execute("SELECT r.* FROM skill_runs r JOIN chats ch ON ch.id=r.chat_id WHERE r.skill='learn' ORDER BY r.updated_at DESC").fetchall()
    out = []
    for r in rows:
        r = dict(r)
        r["state"] = json.loads(r["state"] or "{}")
        r["slots"] = json.loads(r["slots"] or "{}")
        if r["state"].get("path"):
            out.append(r)
    return out


def get_course(run_id: str) -> Optional[dict]:
    return next((r for r in _runs() if r["id"] == run_id), None)


def _module_stats(run: dict) -> list[dict]:
    st = run["state"]
    path = st.get("path") or []
    done = set(st.get("learn_progress") or [])
    hist = st.get("quiz_history") or []
    out = []
    for i, m in enumerate(path):
        key = f"m{i}"
        attempts = [h for h in hist if h.get("module") == key]
        last = attempts[-1] if attempts else None
        out.append({"index": i, "key": key, "title": m.get("title", ""), "done": key in done,
                    "started": key in (st.get("quizzes") or {}) or i <= int(st.get("current", 0)),
                    "attempts": len(attempts), "last_pct": round(100 * last["right"] / max(1, last["total"])) if last else None,
                    "best_pct": max((round(100 * a["right"] / max(1, a["total"])) for a in attempts), default=None),
                    "has_quiz": bool((st.get("quizzes") or {}).get(key))})
    return out


def card_counts(run_id: Optional[str] = None) -> dict:
    cut = _end_of_today()
    q = "SELECT COUNT(*) n, SUM(CASE WHEN due<=? THEN 1 ELSE 0 END) due, SUM(CASE WHEN interval>=21 THEN 1 ELSE 0 END) mature FROM learn_cards WHERE COALESCE(suspended,0)=0"
    args: list = [cut]
    if run_id:
        q += " AND course_id=?"
        args.append(run_id)
    with db.conn() as c:
        r = c.execute(q, args).fetchone()
    return {"total": r["n"] or 0, "due": r["due"] or 0, "mature": r["mature"] or 0}


def courses() -> list[dict]:
    out = []
    for r in _runs():
        mods = _module_stats(r)
        scored = [m["last_pct"] for m in mods if m["last_pct"] is not None]
        with db.conn() as c:
            la = c.execute("SELECT MAX(ts) t FROM learn_events WHERE course_id=?", (r["id"],)).fetchone()["t"]
        out.append({"id": r["id"], "chat_id": r["chat_id"], "subject": str(r["slots"].get("subject") or r["request"])[:80],
                    "level": r["slots"].get("level"), "mode": r["slots"].get("mode"), "book": (r["state"].get("book") or {}).get("name"),
                    "modules": mods, "current": int(r["state"].get("current", 0)), "done": sum(1 for m in mods if m["done"]),
                    "total": len(mods), "avg_quiz": round(sum(scored) / len(scored)) if scored else None,
                    "cards": card_counts(r["id"]), "last_activity": la or r["updated_at"], "created": r["created_at"]})
    return out


# ------------------------------------------------------------------ events, streak
def log_event(course_id: Optional[str], kind: str, module: str = "", right: int = 0, total: int = 0, detail: Optional[dict] = None) -> int:
    with db.conn() as c:
        cur = c.execute("INSERT INTO learn_events(course_id, kind, module, right_n, total_n, detail, ts) VALUES(?,?,?,?,?,?,?)",
                        (course_id, kind, module, int(right), int(total), json.dumps(detail or {}, ensure_ascii=False), _now()))
        return int(cur.lastrowid or 0)


def activity(days: int = 35) -> dict[str, int]:
    since = datetime.now() - timedelta(days=days)
    with db.conn() as c:
        rows = c.execute("SELECT ts FROM learn_events WHERE ts>=?", (since.timestamp(),)).fetchall()
    out: dict[str, int] = {}
    for r in rows:
        d = _day(r["ts"])
        out[d] = out.get(d, 0) + 1
    return out


def streak(act: Optional[dict] = None) -> dict:
    """Consecutive days with any learning activity, counted back from today (a streak survives until the end of today)."""
    with db.conn() as c:
        rows = c.execute("SELECT DISTINCT date(ts,'unixepoch','localtime') d FROM learn_events").fetchall()
    days = {r["d"] for r in rows}
    cur, d = 0, date.today()
    if d.isoformat() not in days:
        d -= timedelta(days=1)
    while d.isoformat() in days:
        cur += 1
        d -= timedelta(days=1)
    best, run, prev = 0, 0, None
    for s in sorted(days):
        dd = date.fromisoformat(s)
        run = run + 1 if prev and (dd - prev).days == 1 else 1
        best, prev = max(best, run), dd
    return {"current": cur, "best": best, "today": date.today().isoformat() in days}


def today_summary() -> dict:
    start = datetime.now().replace(hour=0, minute=0, second=0, microsecond=0).timestamp()
    with db.conn() as c:
        rows = c.execute("SELECT kind, COUNT(*) n, SUM(right_n) r, SUM(total_n) t FROM learn_events WHERE ts>=? GROUP BY kind", (start,)).fetchall()
    return {r["kind"]: {"n": r["n"], "right": r["r"] or 0, "total": r["t"] or 0} for r in rows}


def weak_topics(cs: list[dict], limit: int = 6) -> list[dict]:
    out = []
    for c in cs:
        for m in c["modules"]:
            if m["last_pct"] is not None and m["last_pct"] < 70:
                out.append({"course_id": c["id"], "subject": c["subject"], "module": m["title"], "pct": m["last_pct"], "attempts": m["attempts"]})
    return sorted(out, key=lambda x: x["pct"])[:limit]


def overview() -> dict:
    cs = courses()
    cc = card_counts()
    act = activity()
    return {"courses": cs, "cards": cc, "streak": streak(act), "today": today_summary(), "activity": act, "weak": weak_topics(cs)}


# ------------------------------------------------------------------ flashcards (SM-2)
def add_cards(course_id: str, module: str, cards: list[dict], source: str = "lesson") -> int:
    """Insert validated cards; a card whose front or answer matches one already in the course is skipped."""
    with db.conn() as c:
        rows = c.execute("SELECT front, back FROM learn_cards WHERE course_id=?", (course_id,)).fetchall()
        have_f, have_b = {_norm(r["front"]) for r in rows}, {_norm(r["back"]) for r in rows}
        n = 0
        for card in cards[:MAX_CARDS_PER_LESSON]:
            front, back = str(card.get("front", "")).strip()[:440], str(card.get("back", "")).strip()[:420]
            if len(front) < 4 or len(back) < 2 or _norm(front) in have_f or _norm(front) == _norm(back) or (len(_norm(back)) > 12 and _norm(back) in have_b):
                continue
            have_f.add(_norm(front))
            have_b.add(_norm(back))
            c.execute("INSERT INTO learn_cards(course_id, module, front, back, source, ease, interval, reps, lapses, due, created, kind, page, hint) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                      (course_id, module[:120], front, back, source, 2.5, 0, 0, 0, _now(), _now(),
                       card.get("kind") if card.get("kind") in ("basic", "cloze") else "basic", card.get("page"), str(card.get("hint") or "")[:120]))
            n += 1
    return n


def valid_cards(data: Any) -> list[dict]:
    """Cards in a model reply, in the shape the app stores (basic / cloze, optional hint). Quality filtering happens in flashcards.quality."""
    items = data.get("cards") if isinstance(data, dict) else data
    return [c for c in (flashcards.normalize(it) for it in items or []) if c]


def _settings_int(key: str, default: int) -> int:
    try:
        return max(0, int(db.get_settings().get(key, default)))
    except Exception:  # noqa: BLE001
        return default


def _decorate(row: dict) -> dict:
    """What the review screen needs for one card: scheduling previews, leech and maturity flags."""
    row["leech"] = flashcards.is_leech(row)
    row["maturity"] = flashcards.maturity(row)
    row["preview"] = {g: flashcards.fmt_interval(sm2(row, g)["due"] - _now()) for g in GRADES}
    return row


def due_cards(course_id: Optional[str] = None, limit: int = 30) -> list[dict]:
    """Reviews that are due first (oldest first), then new cards up to the daily limit. Suspended cards never appear."""
    base = "SELECT c.*, COALESCE(json_extract(r.slots,'$.subject'),'') subject FROM learn_cards c LEFT JOIN skill_runs r ON r.id=c.course_id WHERE COALESCE(c.suspended,0)=0"
    scope, args = ("", []) if not course_id else (" AND c.course_id=?", [course_id])
    day_start = datetime.now().replace(hour=0, minute=0, second=0, microsecond=0).timestamp()
    with db.conn() as c:
        seen_today = c.execute("SELECT COUNT(*) n FROM learn_cards WHERE first_seen>=?", (day_start,)).fetchone()["n"]
        reviews = [dict(r) for r in c.execute(base + scope + " AND c.first_seen IS NOT NULL AND c.due<=? ORDER BY c.due ASC LIMIT ?", args + [_end_of_today(), int(limit)]).fetchall()]
        room = max(0, _settings_int("cards_new_per_day", 15) - seen_today)
        news = [dict(r) for r in c.execute(base + scope + " AND c.first_seen IS NULL ORDER BY c.module, c.id LIMIT ?", args + [min(room, max(0, int(limit) - len(reviews)))]).fetchall()]
    return [_decorate(r) for r in (reviews + news)[: int(limit)]]


def sm2(card: dict, grade: str) -> dict:
    """Return the card's new scheduling fields after a review. again resets (back in 10 minutes), hard/good/easy lengthen the gap."""
    q = GRADES[grade]
    ease, reps, interval, lapses = float(card["ease"]), int(card["reps"]), int(card["interval"]), int(card["lapses"])
    if q < 3:
        return {"ease": max(1.3, ease - 0.2), "reps": 0, "interval": 0, "lapses": lapses + 1, "due": _now() + 600}
    ease = max(1.3, ease + 0.1 - (5 - q) * (0.08 + (5 - q) * 0.02))
    reps += 1
    if reps == 1:
        interval = 1 if grade != "easy" else 3
    elif reps == 2:
        interval = 6 if grade != "hard" else 4
    else:
        interval = max(interval + 1, round(interval * ease * (0.85 if grade == "hard" else 1.3 if grade == "easy" else 1.0)))
    return {"ease": ease, "reps": reps, "interval": interval, "lapses": lapses, "due": _now() + interval * 86400}


def grade_card(card_id: int, grade: str) -> Optional[dict]:
    """Grade one review. Returns the new schedule plus what is needed to undo it (prev, event)."""
    if grade not in GRADES:
        return None
    with db.conn() as c:
        row = c.execute("SELECT * FROM learn_cards WHERE id=?", (card_id,)).fetchone()
        if not row:
            return None
        new = sm2(dict(row), grade)
        c.execute("UPDATE learn_cards SET ease=?, reps=?, interval=?, lapses=?, due=?, last_reviewed=?, first_seen=COALESCE(first_seen, ?) WHERE id=?",
                  (new["ease"], new["reps"], new["interval"], new["lapses"], new["due"], _now(), _now(), card_id))
    ev = log_event(row["course_id"], "card", row["module"], 0 if grade == "again" else 1, 1, {"grade": grade, "card": card_id})
    prev = {k: row[k] for k in ("ease", "interval", "reps", "lapses", "due", "last_reviewed", "first_seen")}
    return {"id": card_id, **new, "leech": new["lapses"] >= flashcards.LEECH_LAPSES, "prev": prev, "event": ev}


def undo_grade(card_id: int, prev: dict, event: int = 0) -> bool:
    """Put a card back exactly as it was before its last grade, and take that review out of the statistics."""
    try:
        vals = (float(prev["ease"]), int(prev["interval"]), int(prev["reps"]), int(prev["lapses"]), float(prev["due"]),
                None if prev.get("last_reviewed") is None else float(prev["last_reviewed"]),
                None if prev.get("first_seen") is None else float(prev["first_seen"]))
    except (KeyError, TypeError, ValueError):
        return False
    if not (1.3 <= vals[0] <= 4.0 and 0 <= vals[1] <= 36500 and 0 <= vals[2] <= 1000 and 0 <= vals[3] <= 1000):
        return False
    with db.conn() as c:
        cur = c.execute("UPDATE learn_cards SET ease=?, interval=?, reps=?, lapses=?, due=?, last_reviewed=?, first_seen=? WHERE id=?", (*vals, card_id))
        if event:
            c.execute("DELETE FROM learn_events WHERE id=? AND kind='card'", (event,))
        return cur.rowcount > 0


def update_card(card_id: int, front: str, back: str) -> bool:
    front, back = front.strip()[:440], back.strip()[:420]
    if len(front) < 4 or len(back) < 1:
        return False
    with db.conn() as c:
        return c.execute("UPDATE learn_cards SET front=?, back=? WHERE id=?", (front, back, card_id)).rowcount > 0


def set_suspended(card_id: int, suspended: bool) -> bool:
    with db.conn() as c:
        return c.execute("UPDATE learn_cards SET suspended=? WHERE id=?", (1 if suspended else 0, card_id)).rowcount > 0


def delete_card(card_id: int) -> None:
    with db.conn() as c:
        c.execute("DELETE FROM learn_cards WHERE id=?", (card_id,))


def list_cards(course_id: str) -> list[dict]:
    with db.conn() as c:
        rows = [dict(r) for r in c.execute("SELECT * FROM learn_cards WHERE course_id=? ORDER BY module, id", (course_id,)).fetchall()]
    for r in rows:
        r["leech"], r["maturity"] = flashcards.is_leech(r), flashcards.maturity(r)
    return rows


def card_stats(course_id: Optional[str] = None) -> dict:
    """Numbers for the Cards tab: how many cards are new / learning / young / mature, what is due over the next week, and how often you
    remember (share of reviews in the last 30 days that were not 'again')."""
    where, args = (" WHERE course_id=?", [course_id]) if course_id else ("", [])
    with db.conn() as c:
        rows = [dict(r) for r in c.execute("SELECT interval, reps, due, last_reviewed, lapses, suspended FROM learn_cards" + where, args).fetchall()]
        since = _now() - 30 * 86400
        ev = c.execute("SELECT SUM(right_n) r, SUM(total_n) t FROM learn_events WHERE kind='card' AND ts>=?" + (" AND course_id=?" if course_id else ""),
                       [since] + args).fetchone()
        today = c.execute("SELECT COUNT(*) n FROM learn_events WHERE kind='card' AND ts>=?" + (" AND course_id=?" if course_id else ""),
                          [datetime.now().replace(hour=0, minute=0, second=0, microsecond=0).timestamp()] + args).fetchone()["n"]
    mat = {"new": 0, "learning": 0, "young": 0, "mature": 0, "suspended": 0}
    for r in rows:
        mat[flashcards.maturity(r)] += 1
    start = datetime.now().replace(hour=0, minute=0, second=0, microsecond=0)
    forecast = []
    for i in range(7):
        lo, hi = (start + timedelta(days=i)).timestamp(), (start + timedelta(days=i + 1)).timestamp()
        n = sum(1 for r in rows if not r["suspended"] and r["last_reviewed"] is not None and ((r["due"] < hi) if i == 0 else (lo <= r["due"] < hi)))
        forecast.append({"day": (start + timedelta(days=i)).strftime("%a"), "due": n})
    t = ev["t"] or 0
    return {"total": len(rows), "maturity": mat, "forecast": forecast, "retention": round(100 * (ev["r"] or 0) / t) if t else None, "reviews_30d": t,
            "reviewed_today": today, "leeches": sum(1 for r in rows if flashcards.is_leech(r) and not r["suspended"]),
            "new_per_day": _settings_int("cards_new_per_day", 15)}


# ------------------------------------------------------------------ revisiting old learning
def past_quiz(run_id: str, n: int = 8, seed: Optional[int] = None) -> dict:
    """A mixed quiz from everything learned so far: questions missed before come first, then random older ones."""
    run = get_course(run_id)
    if not run:
        return {"questions": []}
    st = run["state"]
    quizzes = st.get("quizzes") or {}
    titles = {f"m{i}": m.get("title", "") for i, m in enumerate(st.get("path") or [])}
    missed: list[tuple[str, int]] = []
    for h in reversed(st.get("quiz_history") or []):
        for i in h.get("missed", []):
            if (h.get("module"), i) not in missed and i < len((quizzes.get(h.get("module")) or [])):
                missed.append((h.get("module"), i))
    rng = random.Random(seed if seed is not None else int(_now()))
    rest = [(k, i) for k, qs in quizzes.items() for i in range(len(qs)) if (k, i) not in missed]
    rng.shuffle(rest)
    pick = (missed[: max(1, n // 2 + n % 2)] + rest)[:n] if missed else rest[:n]
    qs = []
    for k, i in pick:
        q = dict(quizzes[k][i])
        q["module"], q["module_title"], q["was_missed"] = k, titles.get(k, ""), (k, i) in missed
        qs.append(q)
    rng.shuffle(qs)
    return {"questions": qs, "missed_pool": len(missed)}


def module_tests(run_id: str) -> dict:
    """What Test me shows for a course: each module with the AI's recommended tests (when known) and how many saved quiz questions it has."""
    run = get_course(run_id)
    if not run:
        return {"modules": []}
    st = run["state"]
    plans, quizzes = st.get("plans") or {}, st.get("quizzes") or {}
    out = []
    for m in _module_stats(run):
        out.append({"index": m["index"], "title": m["title"], "started": m["started"], "done": m["done"], "last_pct": m["last_pct"],
                    "plan": plans.get(m["key"]), "quiz_count": len(quizzes.get(m["key"]) or [])})
    return {"subject": str(run["slots"].get("subject") or ""), "modules": out}


def module_quiz(run_id: str, idx: int) -> dict:
    run = get_course(run_id)
    path = (run or {}).get("state", {}).get("path") or []
    if not run or not (0 <= idx < len(path)):
        return {"questions": []}
    return {"title": path[idx].get("title", ""), "questions": list((run["state"].get("quizzes") or {}).get(f"m{idx}") or [])}


# ------------------------------------------------------------------ math practice (deterministic)
def _fmt_frac(f: Fraction) -> str:
    return str(f.numerator) if f.denominator == 1 else f"{f.numerator}/{f.denominator}"


def _p_arith(r: random.Random, lv: int) -> dict:
    if lv == 1:
        a, b = r.randint(12, 99), r.randint(12, 99)
        op = r.choice("+-")
        q = f"{a} {op} {b}"
        return {"q": f"Compute {q}", "answer": str(eval(q)), "kind": "number"}
    if lv == 2:
        if r.random() < 0.5:
            a, b = r.randint(12, 99), r.randint(3, 19)
            return {"q": f"Compute {a} × {b}", "answer": str(a * b), "kind": "number"}
        b, c = r.randint(3, 19), r.randint(4, 40)
        return {"q": f"Compute {b * c} ÷ {b}", "answer": str(c), "kind": "number"}
    a, b, c, d = r.randint(2, 15), r.randint(2, 12), r.randint(2, 9), r.randint(1, 20)
    q = f"{a} + {b} × ({c} + {d}) - {d}"
    return {"q": f"Compute {q}", "answer": str(eval(q.replace("×", "*"))), "kind": "number", "hint": "Brackets first, then multiplication, then add/subtract."}


def _p_frac(r: random.Random, lv: int) -> dict:
    d1, d2 = r.choice([2, 3, 4, 5, 6, 8]), r.choice([2, 3, 4, 5, 6, 8, 9])
    a, b = Fraction(r.randint(1, d1 - 1 if d1 > 1 else 1), d1), Fraction(r.randint(1, d2 - 1), d2)
    op = r.choice("+-×") if lv > 1 else r.choice("+×")
    res = a + b if op == "+" else a - b if op == "-" else a * b
    return {"q": f"Compute {_fmt_frac(a)} {op} {_fmt_frac(b)} (give the answer as a fraction in lowest terms, like 3/4)", "answer": _fmt_frac(res), "kind": "number",
            "hint": "Use a common denominator for + and −; multiply tops and bottoms for ×."}


def _p_percent(r: random.Random, lv: int) -> dict:
    p, n = r.choice([5, 10, 12, 15, 20, 25, 30, 40, 50, 60, 75]), r.choice([40, 60, 80, 120, 150, 200, 240, 360, 500, 800])
    kind = r.randint(0, 2 if lv > 1 else 0)
    if kind == 0:
        return {"q": f"What is {p}% of {n}?", "answer": f"{n * p / 100:g}", "kind": "number"}
    if kind == 1:
        return {"q": f"A price of {n} is increased by {p}%. What is the new price?", "answer": f"{n * (100 + p) / 100:g}", "kind": "number"}
    m = n * r.choice([2, 3, 4, 5])
    return {"q": f"{n} is what percent of {m}? (round to 2 decimals if needed)", "answer": f"{100 * n / m:g}", "kind": "number", "tol": 0.01}


def _p_algebra(r: random.Random, lv: int) -> dict:
    x = r.randint(-9, 12)
    if lv == 1:
        a, b = r.randint(2, 9), r.randint(-15, 20)
        return {"q": f"Solve for x: {a}x {'+' if b >= 0 else '−'} {abs(b)} = {a * x + b}", "answer": str(x), "kind": "number"}
    if lv == 2:
        a, c = r.randint(3, 9), r.randint(1, 2)
        b = r.randint(-10, 10)
        e = b + (a - c) * x  # a x + b = c x + e  has the solution x
        sgn = lambda v: ("+" if v >= 0 else "−") + f" {abs(v)}"  # noqa: E731
        return {"q": f"Solve for x: {a}x {sgn(b)} = {c if c != 1 else ''}x {sgn(e)}", "answer": str(x), "kind": "number", "hint": "Collect the x terms on one side first."}
    a, b = r.randint(2, 6), r.randint(1, 9)
    return {"q": f"Solve for x: (x + {b}) / {a} = {Fraction(x + b, a) if (x + b) % a else (x + b) // a}", "answer": str(x), "kind": "number"}


def _p_quad(r: random.Random, lv: int) -> dict:
    r1, r2 = (r.randint(1, 8), r.randint(1, 8)) if lv == 1 else (r.randint(-9, 9), r.randint(-9, 9))
    a = 1 if lv < 3 else r.randint(2, 4)
    b, c = -a * (r1 + r2), a * r1 * r2

    def term(co, p):
        if co == 0:
            return ""
        s = "+" if co > 0 else "−"
        v = abs(co)
        body = (f"{v}" if v != 1 or p == "" else "") + p
        return f" {s} {body}"

    expr = (f"{a if a != 1 else ''}x²" + term(b, "x") + term(c, "")).strip()
    return {"q": f"Find all solutions of {expr} = 0 (separate with a comma)", "answer": ", ".join(str(v) for v in sorted({r1, r2})), "kind": "set",
            "hint": "Look for two numbers that multiply to c/a and add to −b/a, or use the quadratic formula."}


def _p_calc(r: random.Random, lv: int) -> dict:
    import sympy as sp
    x = sp.Symbol("x")
    a, b, n = r.randint(2, 9), r.randint(1, 9), r.randint(2, 6)
    if lv == 1:
        f = a * x ** n + b * x
        return {"q": f"Differentiate f(x) = {a}x^{n} + {b}x with respect to x", "answer": str(sp.diff(f, x)), "kind": "expr"}
    if lv == 2:
        if r.random() < 0.5:
            f = a * sp.sin(x) + b * sp.exp(x)
            return {"q": f"Differentiate f(x) = {a}sin(x) + {b}e^x", "answer": str(sp.diff(f, x)), "kind": "expr"}
        f = a * x ** n
        return {"q": f"Find the indefinite integral of {a}x^{n} (leave out + C)", "answer": str(sp.integrate(f, x)), "kind": "expr"}
    f = x ** 2 * sp.sin(x)
    k = r.randint(2, 5)
    return {"q": f"Differentiate f(x) = {k}x^2 sin(x)", "answer": str(sp.diff(k * f, x)), "kind": "expr", "hint": "Product rule: (uv)' = u'v + uv'."}


def _p_stats(r: random.Random, lv: int) -> dict:
    data = [r.randint(2, 40) for _ in range(r.randint(5, 8))]
    s = ", ".join(map(str, data))
    which = r.choice(["mean", "median"] + (["standard deviation"] if lv == 3 else []))
    if which == "mean":
        return {"q": f"Find the mean of {s} (round to 2 decimals if needed)", "answer": f"{statistics.mean(data):.4f}", "kind": "number", "tol": 0.011}
    if which == "median":
        return {"q": f"Find the median of {s}", "answer": f"{statistics.median(data):g}", "kind": "number"}
    return {"q": f"Find the population standard deviation of {s} (round to 2 decimals)", "answer": f"{statistics.pstdev(data):.4f}", "kind": "number", "tol": 0.011}


def _p_word(r: random.Random, lv: int) -> dict:
    t = r.randint(0, 3)
    if t == 0:
        sp_, h = r.choice([40, 50, 60, 72, 80]), r.choice([2, 3, 4, 5])
        return {"q": f"A car travels at {sp_} km/h for {h} hours. How far does it go (km)?", "answer": str(sp_ * h), "kind": "number"}
    if t == 1:
        p, rate, y = r.choice([5000, 8000, 10000, 20000]), r.choice([4, 5, 6, 8]), r.choice([2, 3, 5])
        return {"q": f"Simple interest on {p} at {rate}% per year for {y} years?", "answer": f"{p * rate * y / 100:g}", "kind": "number"}
    if t == 2:
        a, b, c = r.randint(60, 95), r.randint(60, 95), r.randint(60, 95)
        return {"q": f"Test scores are {a}, {b} and {c}. What score on a fourth test gives an average of 80? (negative or over 100 is possible here, just compute)", "answer": str(320 - a - b - c), "kind": "number"}
    d, h = r.choice([120, 150, 180, 240]), r.choice([2, 3, 4, 5, 6])
    return {"q": f"{d} km is covered in {h} hours. What is the average speed in km/h (round to 1 decimal)?", "answer": f"{d / h:.4f}", "kind": "number", "tol": 0.051}


TOPICS = {"arithmetic": _p_arith, "fractions": _p_frac, "percent": _p_percent, "algebra": _p_algebra, "quadratics": _p_quad,
          "calculus": _p_calc, "statistics": _p_stats, "word problems": _p_word}
TOPIC_WORDS = {"calculus": r"calculus|derivative|integral|differentiat", "quadratics": r"quadratic|polynomial|factori[sz]|roots", "statistics": r"statistic|probabilit|mean|median|data analysis",
               "algebra": r"algebra|equation|linear|inequalit", "fractions": r"fraction|decimal", "percent": r"percent|ratio|proportion|interest",
               "arithmetic": r"arithmetic|number|maths?|mathematics|basic", "word problems": r"word problem|speed|distance"}


def math_topic(*texts: str) -> Optional[str]:
    """The practice topic that matches a subject / module title, or None when it is not a maths subject."""
    t = " ".join(texts).lower()
    if not re.search(r"\bmaths?\b|mathematics|algebra|calculus|arithmetic|fraction|percent|quadratic|statistic|geometry|trigonometr|equation|derivative|integral|probabilit", t):
        return None
    for topic, rx in TOPIC_WORDS.items():
        if re.search(rx, t):
            return topic
    return "arithmetic"


def math_problems(topic: str, level: int = 1, n: int = 6, seed: Optional[int] = None) -> list[dict]:
    fn = TOPICS.get(topic) or TOPICS["arithmetic"]
    lv = max(1, min(3, int(level)))
    r = random.Random(seed if seed is not None else int(_now() * 1000) % 10_000_000)
    out, seen = [], set()
    for _ in range(n * 25):
        if len(out) >= n:
            break
        p = fn(r, lv)
        if p["q"] in seen:
            continue
        seen.add(p["q"])
        p["id"] = uuid.uuid4().hex[:8]
        out.append(p)
    return out


_SAFE = re.compile(r"^[0-9a-zA-Z+\-*/^().,\s=−×÷²]*$")


def _num(s: str) -> Optional[Fraction]:
    s = s.strip().replace("−", "-").replace(",", "").replace("x=", "").replace("x =", "").replace("%", "")
    try:
        return Fraction(s)
    except (ValueError, ZeroDivisionError):
        try:
            return Fraction(str(float(s)))
        except ValueError:
            return None


def check_answer(kind: str, expected: str, given: str, tol: float = 0.0) -> dict:
    given = (given or "").strip()[:80]
    if not given or not _SAFE.match(given):
        return {"correct": False, "message": "Enter a number or an expression using digits and + - * / ^ ( )."}
    if kind == "number":
        g, e = _num(given), _num(expected)
        if g is None or e is None:
            return {"correct": False, "message": "Could not read that as a number (a fraction like 3/4 is fine)."}
        ok = abs(float(g) - float(e)) <= (tol or 1e-9)
        return {"correct": ok, "answer": expected}
    if kind == "set":
        parts = [p for p in re.split(r"[,;]|\band\b", given.replace("x=", "").replace("x =", "")) if p.strip()]
        gs = {_num(p) for p in parts}
        es = {_num(p) for p in expected.split(",")}
        return {"correct": None not in gs and gs == es, "answer": expected}
    try:
        import sympy as sp
        from sympy.parsing.sympy_parser import parse_expr, standard_transformations, implicit_multiplication_application, convert_xor
        tr = standard_transformations + (implicit_multiplication_application, convert_xor)
        g = parse_expr(given.replace("−", "-").replace("×", "*").replace("²", "**2"), transformations=tr, local_dict={"e": sp.E})
        e = parse_expr(expected, transformations=tr)
        return {"correct": bool(sp.simplify(g - e) == 0), "answer": expected}
    except Exception:  # noqa: BLE001 - unparsable input is simply a wrong answer
        return {"correct": False, "message": "Could not read that expression. Write it like 6*x^2 + 3 or 2sin(x)."}


# ------------------------------------------------------------------ code lab
LAB_MAX_CODE = 20_000


def _harness(code: str, tests: list[str]) -> str:
    return (code + "\n\nimport json as __j\n__r = []\nfor __t in " + repr(tests) + ":\n    try:\n        exec(__t, globals())\n        __r.append([__t, True, ''])\n"
            "    except BaseException as __e:\n        __r.append([__t, False, type(__e).__name__ + ': ' + str(__e)[:160]])\nprint('\\n@@TESTS@@' + __j.dumps(__r))\n")


async def run_python(code: str, tests: Optional[list[str]] = None, timeout: int = 10) -> dict:
    """Run learner code in the same guarded sandbox as the run_python tool (no network, scrubbed env, time limit). With tests, each assertion is reported."""
    from . import tools
    code = (code or "")[:LAB_MAX_CODE]
    if not code.strip():
        return {"ok": False, "stdout": "", "stderr": "Write some code first.", "tests": [], "passed": 0, "timed_out": False}
    tests = [t for t in (tests or []) if isinstance(t, str) and t.strip()][:12]
    folder = db.DATA_DIR / "lab" / uuid.uuid4().hex[:10]
    folder.mkdir(parents=True, exist_ok=True)
    (db.DATA_DIR / "mplconfig").mkdir(exist_ok=True)
    f = folder / "solution.py"
    f.write_text(_harness(code, tests) if tests else code, encoding="utf-8")
    proc = await asyncio.create_subprocess_exec(sys.executable, "-X", "utf8", str(tools.RUNNER), str(f), cwd=str(folder), env=tools._scrubbed_env(),
                                                stdin=asyncio.subprocess.DEVNULL, stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.PIPE)
    timed_out = False
    try:
        out_b, err_b = await asyncio.wait_for(proc.communicate(), timeout=max(1, min(timeout, 60)))
    except asyncio.TimeoutError:
        timed_out = True
        proc.kill()
        out_b, err_b = await proc.communicate()
    finally:
        import shutil
        shutil.rmtree(folder, ignore_errors=True)
    out = out_b.decode("utf-8", "replace")
    err = err_b.decode("utf-8", "replace")
    results: list = []
    m = re.search(r"\r?\n?@@TESTS@@(.*)\s*$", out, re.S)
    if m:
        try:
            results = [{"test": t, "ok": ok, "error": e} for t, ok, e in json.loads(m.group(1))]
        except ValueError:
            results = []
        out = out[:m.start()]
    clip = lambda t, n=5000: t if len(t) <= n else t[:n] + f"\n…[{len(t) - n:,} more characters]"  # noqa: E731
    passed = sum(1 for t in results if t["ok"])
    return {"ok": proc.returncode == 0 and not timed_out, "stdout": clip(out), "stderr": clip(err), "tests": results, "passed": passed,
            "total": len(tests), "timed_out": timed_out}


async def verified_exercises(items: Any, limit: int = 3) -> list[dict]:
    """Keep only exercises whose reference solution passes ALL of their own tests when actually run. Broken ones (a wrong test, a typo) never reach the learner."""
    good = []
    for it in (items.get("exercises") if isinstance(items, dict) else items) or []:
        if not isinstance(it, dict):
            continue
        task, sol = str(it.get("task", "")).strip(), str(it.get("solution", "")).strip("\n")
        tests = [str(t).strip() for t in it.get("tests") or [] if str(t).strip().startswith("assert")][:6]
        if not task or not sol or len(tests) < 2:
            continue
        res = await run_python(sol, tests, timeout=10)
        if res["ok"] and res["total"] and res["passed"] == res["total"]:
            good.append({"task": task[:400], "starter": str(it.get("starter") or "").strip("\n")[:800], "tests": tests, "hint": str(it.get("hint") or "")[:240], "solution": sol[:1500]})
        if len(good) >= limit:
            break
    return good
